import React, { useState } from 'react';
import { CInlineEdit } from '@cloud-materials/common';

function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export default () => {
  const [value, setValue] = useState('向风而行');
  const onSubmit = async (result: string) => {
    await sleep(2000);
    setValue(result);
  };

  return (
    <>
      <CInlineEdit editTips="提示文案" onSubmit={onSubmit} value={value} />
    </>
  );
};

import React, { useState } from 'react';
import { CInlineEdit, Space, Typography } from '@cloud-materials/common';

const options = ['你站在桥上看风景', '看风景的人在楼上看你', '明月装饰了你的窗子', '你装饰了别人的梦'];

export default () => {
  const [numberValue, setNumberValue] = useState(123);
  const [textareaValue, setTextareaValue] = useState('向风而行');
  const [selectValue, setSelectValue] = useState('你站在桥上看风景');

  return (
    <Space direction="vertical">
      <Typography.Title heading={3}>Input Number</Typography.Title>
      <CInlineEdit value={numberValue} onSubmit={setNumberValue} field={{ component: 'InputNumber' }} />
      <Typography.Title heading={3}>Textarea</Typography.Title>
      <CInlineEdit value={textareaValue} onSubmit={setTextareaValue} field={{ component: 'TextArea' }} />
      <Typography.Title heading={3}>Select</Typography.Title>
      <CInlineEdit
        value={selectValue}
        onSubmit={setSelectValue}
        field={{ component: 'Select', componentProps: { options } }}
      />
    </Space>
  );
};

