import React, { useState } from 'react';
import { CInlineEdit } from '@cloud-materials/common';

export default () => {
  CInlineEdit.config({
    name: {
      emptyData: '暂无名称',
      rules: [
        {
          validator(value: string | undefined, cb) {
            if (value?.includes('a')) {
              return cb('实例名称中不能包含a字符');
            }
            return cb();
          },
          message: '实例名称中不能包含a字符',
        },
      ],
    },
  });

  const [value, setValue] = useState('向风而行');
  const onSubmit = async (result: string) => {
    setValue(result);
  };

  return (
    <>
      <CInlineEdit bizType="name" onSubmit={onSubmit} value={value} />
    </>
  );
};

import React, { useState } from 'react';
import { CInlineEdit } from '@cloud-materials/common';

function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export default () => {
  const [value, setValue] = useState('向风而行');

  const onSubmit = async (result: string) => {
    await sleep(2000);
    setValue(result);
  };

  const asyncValidate = async () => {
    await sleep(2000);
    return '配置异步校验 onBlur 触发，且永不通过';
  };

  return (
    <>
      <CInlineEdit
        rules={[
          {
            required: true,
            message: '请输入实例名称',
          },
          {
            message: '长度需要在2-128个字符内',
            minLength: 2,
            maxLength: 128,
          },
        ]}
        enableAsyncValidateWhenBlur
        onSubmit={onSubmit}
        value={value}
        asyncValidator={asyncValidate}
      />
    </>
  );
};

